# WAR ARENA - Per-User Daily Usage Limits (by tier) - Installer
# Caps scans/monitors per user per rolling 24h by tier. Protects free-tier
# resources; applies ALWAYS (even during the promo window). COMMAND = unlimited.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-usage-limits.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Per-user daily usage limits installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/pricing/usageLimiter.ts" ""
Write-B64 "src/product/pricing/pricing.ts" ""
Write-B64 "src/integration/warRuntime.ts" ""
Write-B64 "src/api/wiredApp.ts" ""
Write-B64 "tests/unit/usageLimiter.test.ts" ""
Write-B64 "tests/integration/wiredApi.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Usage limits installed. Expected: 1002 passed + 1 skipped, 468 guards." -ForegroundColor Green
Write-Host "Defaults: STANDARD 20 scans + 3 monitors/day; COMMAND unlimited." -ForegroundColor Yellow
